"""Render a problem as an LSD input file.

The order follows LSD's requirements: atoms, then HSQC (which defines the protons),
then HMBC and COSY, then bonds, solver options and the ring filters. Atom ids map to
consecutive LSD indices, so gaps left by removed atoms never reach the solver.
"""

from __future__ import annotations

from ailsa.case.model import Correlation, Problem

HEADER = (
    "; Generated by `ailsa case solve`. Do not edit: change the problem with `ailsa case edit`."
)


def lsd_index(problem: Problem) -> dict[int, int]:
    """Atom id -> LSD atom index (1-based, in atom order)."""
    return {a.id: i for i, a in enumerate(problem.atoms, start=1)}


def _methyl_to_sp2(problem: Problem, corr: Correlation) -> bool:
    """An HMBC from methyl protons to an sp2 carbon: four-bond couplings are common."""
    if problem.atom(corr.y).hydrogens != 3:
        return False
    return all(problem.atom(x).hyb == 2 for x in corr.x)


def render(problem: Problem, elim: int, max_solutions: int, methyl_4j: bool = False) -> str:
    """The LSD input for ``problem`` with an ELIM budget and a solution limit.

    With ``methyl_4j``, HMBC correlations from methyl protons to sp2 carbons may span
    up to four bonds. LSD never eliminates a correlation with an explicit range.
    """
    idx = lsd_index(problem)
    lines = [HEADER, f"; formula {problem.formula}", ""]

    for a in problem.atoms:
        what = a.mult if a.element == "C" else f"{a.element}, {a.hydrogens} H"
        shift = f" {a.shift:.2f}" if a.shift is not None else ""
        copy = f", copy of {problem.atom(a.copy_of).label}" if a.copy_of else ""
        lines.append(
            f"MULT {idx[a.id]} {a.element} {a.hyb} {a.hydrogens}"
            f"    ; {a.label}{shift} {what} sp{a.hyb}{copy}"
        )
    lines.append("")

    used = [c for c in problem.correlations if c.use]
    referenced = {c.y for c in used} | {x for c in used if c.kind == "COSY" for x in c.x}
    for a in problem.atoms:
        if a.hydrogens == 0:
            continue
        if a.element != "C" and a.id not in referenced:
            continue
        note = ", ".join(f"{h:.2f}" for h in a.h_shifts) or "exchangeable"
        lines.append(f"HSQC {idx[a.id]} {idx[a.id]}    ; H on {a.label}: {note}")
    lines.append("")

    for c in used:
        group = [idx[x] for x in c.x]
        p1 = str(group[0]) if len(group) == 1 else "(" + " ".join(map(str, group)) + ")"
        note = f"{c.id} {c.c_shift:.2f}/{c.h_shift:.2f}" + (f" snr {c.snr:.0f}" if c.snr else "")
        span = ""
        if c.kind == "HMBC" and methyl_4j and _methyl_to_sp2(problem, c):
            span, note = " 2 4", note + ", methyl protons: up to four bonds"
        lines.append(f"{c.kind} {p1} {idx[c.y]}{span}    ; {note}")
    if used:
        lines.append("")

    for b in problem.bonds:
        lines.append(f"BOND {idx[b.a]} {idx[b.b]}    ; {b.reason}")
    if problem.bonds:
        lines.append("")

    if elim > 0:
        lines.append(f"ELIM {elim} 0    ; the solver may drop up to {elim} correlation(s)")
    lines.append(f"MAXS {max_solutions}")
    if not problem.small_rings_allowed:
        lines += [
            'DEFF F1 "ring3"    ; no three-membered rings',
            'DEFF F2 "ring4"    ; no four-membered rings',
            'FEXP "NOT F1 AND NOT F2"',
        ]
    lines += ["", "EXIT", ""]
    return "\n".join(lines)
